import{_ as t,o as r,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Meetup June 4th, 2025","description":"","frontmatter":{"title":"Ceph Developer Meetup June 4th, 2025","date":"2025-06-04T00:00:00.000Z","updated":"2025-06-05T00:00:00.000Z","tags":["Ceph","审计日志","OpenTelemetry","分布式存储","数据库"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Meetup_June_4th_2025.md","filePath":"posts/2025/Ceph_Developer_Meetup_June_4th_2025.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Ceph_Developer_Meetup_June_4th_2025.md"};function i(n,e,s,p,h,u){return r(),l("div",null,[...e[0]||(e[0]=[o('<p>在2025年6月4日的Ceph开发者月度会议上，与会者讨论了Ceph审计日志（Audit Logs）的设计与实现。以下是对会议内容的总结：</p><h3 id="会议背景与目标" tabindex="-1">会议背景与目标 <a class="header-anchor" href="#会议背景与目标" aria-label="Permalink to &quot;会议背景与目标&quot;">​</a></h3><ul><li><strong>提案人</strong>：来自CFS团队的Daria</li><li><strong>核心需求</strong>：当前Ceph集群中，用户执行某些命令可能导致集群状态异常，缺乏审计机制，难以定位问题根源。</li><li><strong>目标</strong>：实现一个集中化的审计日志系统，记录所有Ceph命令。</li></ul><h3 id="主要讨论议题" tabindex="-1">主要讨论议题 <a class="header-anchor" href="#主要讨论议题" aria-label="Permalink to &quot;主要讨论议题&quot;">​</a></h3><ul><li><strong>设计方案</strong>： <ul><li><strong>数据来源</strong>：Monitor、Manager、独立工具。</li><li><strong>存储后端</strong>：首选libsqlite（基于SQLite 3），通过RADOS交互。挑战包括Monitor日志通过MGR路由，但MGR可能不可用。</li></ul></li><li><strong>替代方案讨论</strong>： <ul><li><strong>现有技术</strong>：OpenTelemetry，已在RGW和OSD中用于端到端追踪。</li><li><strong>性能与可靠性</strong>：未启用时零开销；启用后性能影响取决于日志量，数据可能因缓冲或网络问题丢失。</li></ul></li><li><strong>功能扩展与配置</strong>： <ul><li><strong>日志保留策略</strong>：默认按时间或大小修剪，支持用户自定义配置，关键操作永久保留。</li><li><strong>多组件需求</strong>：RGW团队希望记录<code>radosgw-admin</code>命令，Core团队关注时间戳和延迟数据。</li></ul></li></ul><h3 id="关键决策与行动计划" tabindex="-1">关键决策与行动计划 <a class="header-anchor" href="#关键决策与行动计划" aria-label="Permalink to &quot;关键决策与行动计划&quot;">​</a></h3><ul><li><strong>技术选型</strong>：优先评估OpenTelemetry的适用性，若不满足需求，推进原生libsqlite方案。</li><li><strong>日志范围</strong>：覆盖所有Ceph子系统的关键命令，支持按组件和用户角色过滤日志。</li><li><strong>后续行动</strong>： <ul><li><strong>短期</strong>：Daria团队研究OpenTelemetry的Monitor集成可能性，与RGW团队协作。</li><li><strong>长期</strong>：设计统一的审计日志API，支持动态配置，集成到<code>cephadm</code>部署流程。</li></ul></li></ul><h3 id="其他要点" tabindex="-1">其他要点 <a class="header-anchor" href="#其他要点" aria-label="Permalink to &quot;其他要点&quot;">​</a></h3><ul><li><strong>性能与可靠性权衡</strong>：OpenTelemetry的UDP传输可能丢包，需评估是否可接受；原生方案需解决MGR单点故障问题。</li><li><strong>社区协作</strong>：欢迎其他组件提出审计需求，确保设计通用性。</li></ul><h3 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h3><p>待定（根据需要进一步讨论设计进展）。</p><h3 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h3><p>Daria、Patrick、Weni、Mahesh、John、Casey等。</p><p>本次会议重点讨论了Ceph审计日志的设计与实现，包括数据来源、存储后端、替代方案、功能扩展与配置、决策与行动计划等。会议还探讨了性能与可靠性权衡以及社区协作的重要性。</p>',14)])])}const _=t(a,[["render",i]]);export{d as __pageData,_ as default};
